source='''def transform(grid):
    grid = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    sep_candidates = {}
    for r, row in enumerate(grid):
        if row and row[0] != 0 and len(set(row)) == 1:
            sep_candidates.setdefault(row[0], [[], []])[0].append(r)
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if col and col[0] != 0 and len(set(col)) == 1:
            sep_candidates.setdefault(col[0], [[], []])[1].append(c)
    sep = max(sep_candidates, key=lambda color: len(sep_candidates[color][0]) + len(sep_candidates[color][1]))
    sep_rows, sep_cols = sep_candidates[sep]
    row_groups = []
    start = 0
    for r in sep_rows:
        if start < r:
            row_groups.append(list(range(start, r)))
        start = r + 1
    if start < h:
        row_groups.append(list(range(start, h)))
    col_groups = []
    start = 0
    for c in sep_cols:
        if start < c:
            col_groups.append(list(range(start, c)))
        start = c + 1
    if start < w:
        col_groups.append(list(range(start, w)))
    # The shape outside the first column of compartments is the template.
    template = set()
    for rg in row_groups:
        for cg in col_groups[1:]:
            for ri, r in enumerate(rg):
                for ci, c in enumerate(cg):
                    if grid[r][c] not in (0, sep):
                        template.add((ri, ci))
    colors = []
    for rg in row_groups:
        found = [grid[r][c] for r in rg for c in col_groups[0] if grid[r][c] not in (0, sep)]
        colors.append(found[0])
    for bi, rg in enumerate(row_groups):
        for cg in col_groups:
            for r in rg:
                for c in cg:
                    grid[r][c] = colors[bi] if (r-rg[0], c-cg[0]) in template else 0
    return grid
'''
